"""Curación reproducible. Las fechas son hipótesis citadas, no resultados del código."""
import copy, json, csv, hashlib
from pathlib import Path
from urllib.parse import quote

ROOT = Path(__file__).resolve().parents[1]
PILOT = ROOT / 'research' / 'sirach-pilot.json'
D = json.loads(PILOT.read_text())
M = {}
def p(es, en):
    if es != en: M[es] = en
    return es
def save(path, value):
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
def bound(y):
    return None if y is None else {'year':abs(y), 'era':'BCE' if y < 0 else 'CE'}
WORK = {w['canonical_order']:w for w in D['works']}
english = ['Genesis','Exodus','Leviticus','Numbers','Deuteronomy','Joshua','Judges','Ruth','1 Samuel','2 Samuel','1 Kings','2 Kings','1 Chronicles','2 Chronicles','Ezra','Nehemiah','Tobit','Judith','Esther','1 Maccabees','2 Maccabees','Job','Psalms','Proverbs','Ecclesiastes','Song of Songs','Wisdom','Sirach','Isaiah','Jeremiah','Lamentations','Baruch','Ezekiel','Daniel','Hosea','Joel','Amos','Obadiah','Jonah','Micah','Nahum','Habakkuk','Zephaniah','Haggai','Zechariah','Malachi','Matthew','Mark','Luke','John','Acts','Romans','1 Corinthians','2 Corinthians','Galatians','Ephesians','Philippians','Colossians','1 Thessalonians','2 Thessalonians','1 Timothy','2 Timothy','Titus','Philemon','Hebrews','James','1 Peter','2 Peter','1 John','2 John','3 John','Jude','Revelation']
intro = {}
audit=[]
previous_audit={item['book_id']:item for item in json.loads((ROOT/'research/audit.json').read_text())} if (ROOT/'research/audit.json').exists() else {}
for n,w in WORK.items():
    p(w['label'],english[n-1]); w['study_status']='piloto_parcial'
    if n != 28: w['scope_notes']=''
    cache_n={10:9,12:11}.get(n,n)
    cache=ROOT/'.research-cache'/f'{cache_n:02}.json'
    if cache.exists():
        c=json.loads(cache.read_text());url=c['url'];digest=c.get('sha256')
    else:
        url='https://www.biblegateway.com/passage/intro/?search='+quote(english[cache_n-1])+'&version=NABRE';digest=previous_audit.get(w['id'],{}).get('private_capture_sha256')
    sid=f'src_intro_{cache_n:02}'
    intro[n]=sid
    if not any(s['id']==sid for s in D['sources']):
        D['sources'].append(dict(id=sid,title='NABRE / USCCB — Introduction: '+english[cache_n-1],url=url,kind='secondary_synthesis',consulted_on='2026-10-06'))
    audit.append(dict(book_id=w['id'],source_id=sid,url=url,consulted_on='2026-10-06',private_capture_sha256=digest,joint_introduction=cache_n!=n))

uncertain=p('La subdivisión es una propuesta de trabajo; no reconstruye todas las intervenciones ni el ejemplar final.', 'This subdivision is a working proposal; it does not reconstruct every intervention or the final exemplar.')
anonymous=p('Responsable anónimo; no se asignan nacimiento, muerte ni una biografía conjetural.', 'Anonymous author or editor; no conjectural birth, death or biography is assigned.')
working=p('Estimación de la síntesis consultada, conservada con sus límites. No equivale a un consenso demostrado.', 'Estimate from the consulted synthesis, retained with its limitations. It is not a demonstrated consensus.')
form_note=p('Forma textual pertinente por determinar. La fecha de una etapa no prueba su circulación ni su accesibilidad.', 'The pertinent textual form remains to be identified. A stage date does not establish its circulation or accessibility.')

def add(n, key='', label=None, kind='composition', dates=(None,None), scope=None, notes=None, languages=None, actor=None, place=None, event='composition', date_notes=None):
    w=WORK[n]; suffix=w['id'][5:]+('_'+key if key else '')
    sid='stage_'+suffix;aid='actor_'+suffix;atid='attr_'+suffix;cid='claim_'+suffix;eid='ev_'+suffix;did='date_'+suffix
    label=label or (w['label']+' · composición / edición conservada',english[n-1]+' · surviving composition / edition')
    scope=scope or ('Texto del libro conservado, sin atribuirlo a una sola intervención.', 'The surviving book text, without attributing it to a single intervention.')
    notes=notes or ('Se conserva un nodo amplio hasta disponer de una reconstrucción de capas mejor documentada.', 'A broad node is retained pending a better documented reconstruction of its layers.')
    languages=languages if languages is not None else (['el'] if n>46 else ['he'])
    actor=actor or (p('Responsable anónimo de '+w['label'],'Anonymous author or editor of '+english[n-1]),'unknown',anonymous)
    dn=p(*(date_notes or ('La fuente consultada no delimita una fecha de composición final. Se deja abierta.', 'The consulted source does not delimit final composition. It is left open.')))
    citations=[dict(source_id=intro[n],locator=p('Introducción: composición, atribución y estructura del libro.','Introduction: composition, authorship and structure.'))]
    if n==14:citations.append(dict(source_id=intro[13],locator=p('Introducción: contexto del Cronista a finales del siglo V a. C.', 'Introduction: the Chronicler’s late fifth-century BCE setting.')))
    ev=dict(id=eid,kind='secondary_historical_synthesis',basis_id='basis_intro_'+suffix,summary=dn,citations=citations,supports_claim_ids=[cid],limitations=[working])
    claim=dict(id=cid,subject_id=sid,predicate='stage_reconstruction',value=p(*label),evidence_ids=[eid],status='working_hypothesis',certainty_rationale=working,counterarguments=[uncertain])
    D['evidence'].append(ev);D['claims'].append(claim)
    D['actors'].append(dict(id=aid,label=actor[0],kind=actor[1],life_date_ids=[],activity_date_ids=[],claim_ids=[cid],notes=actor[2]))
    D['attributions'].append(dict(id=atid,stage_id=sid,actor_id=aid,relation={'collection':'collector','translation':'translator','redaction':'redactor','revision':'redactor'}.get(kind,'composer'),claim_ids=[cid],status='working_attribution'))
    lo,hi=dates
    dkind='unknown' if lo is None and hi is None else 'upper_bound' if lo is None else 'lower_bound' if hi is None else 'estimated_point' if lo==hi else 'estimated_interval'
    D['dates'].append(dict(id=did,subject_id=sid,event=event,earliest=bound(lo),latest=bound(hi),earliest_inclusive=True,latest_inclusive=True,kind=dkind,claim_ids=[cid],notes=dn))
    contexts=[]
    if place:
        ctxid='context_'+suffix
        D['contexts'].append(dict(id=ctxid,label=p('Contexto propuesto de '+w['label'],'Proposed context of '+english[n-1]),place=p(*place),languages=languages,claim_ids=[cid],notes=p('Localización propuesta en la fuente; no acredita una red de transmisión.','Location proposed in the source; it does not establish a transmission network.')));contexts=[ctxid]
    D['stages'].append(dict(id=sid,work_id=w['id'],label=p(*label),kind=kind,scope=p(*scope),languages=languages,attribution_ids=[atid],date_ids=[did],context_ids=contexts,claim_ids=[cid],historical_status='working_hypothesis',notes=p(*notes)))
    D['forms'].append(dict(id='form_'+suffix,stage_id=sid,language=languages[0] if len(languages)==1 else None,scope=p(*scope),existence_date_ids=[did],availability_claim_ids=[],notes=form_note))
    return sid

