def alternative(suffix,lo,hi,author,notes):
    sid='stage_'+suffix;did='date_alt_'+suffix;atid='attr_alt_'+suffix;aid='actor_alt_'+suffix;cid='claim_alt_'+suffix;eid='ev_alt_'+suffix
    st=next(s for s in D['stages'] if s['id']==sid);base=next(a for a in D['attributions'] if a['id']==st['attribution_ids'][0]);n=next(n for n,w in WORK.items() if w['id']==st['work_id'])
    D['actors'].append(dict(id=aid,label=p(*author),kind='identified_person',life_date_ids=[],activity_date_ids=[],claim_ids=[cid],notes=p(*notes)))
    D['attributions'].append(dict(id=atid,stage_id=sid,actor_id=aid,relation=base['relation'],claim_ids=[cid],status='disputed'));st['attribution_ids'].append(atid)
    D['claims'].append(dict(id=cid,subject_id=sid,predicate='alternative_attribution_and_date',value=p(*notes),evidence_ids=[eid],status='disputed',certainty_rationale=working,counterarguments=[p('Propuesta alternativa, sin convertir el nombre tradicional en una identificación demostrada.', 'Alternative proposal, without treating the traditional name as a demonstrated identification.')]))
    D['evidence'].append(dict(id=eid,kind='secondary_historical_synthesis',basis_id='basis_alt_'+suffix,summary=p(*notes),citations=[dict(source_id=intro[n],locator=p('Introducción: alternativas de atribución y datación.','Introduction: alternative authorship and dating.'))],supports_claim_ids=[cid],limitations=[working]))
    D['dates'].append(dict(id=did,subject_id=sid,event='composition',earliest=bound(lo),latest=bound(hi),earliest_inclusive=True,latest_inclusive=True,kind='upper_bound' if lo is None else 'estimated_interval',claim_ids=[cid],notes=p(*notes)));st['date_ids'].append(did);st['claim_ids'].append(cid)
    return sid,atid,did,cid
