def source(sid,title,url,kind):
    if not any(s['id']==sid for s in D['sources']):D['sources'].append(dict(id=sid,title=title,url=url,kind=kind,consulted_on='2026-10-06'))
def passage(ref):
    sid='src_text_'+hashlib.sha256(ref.encode()).hexdigest()[:10]
    source(sid,'NABRE — '+ref,'https://www.biblegateway.com/passage/?search='+quote(ref)+'&version=NABRE','primary_text_in_translation')
    return sid

def ref_es(ref):
    labels={english[n-1]:w['label'] for n,w in WORK.items()};labels['Psalm']='Salmos'
    for name in sorted(labels,key=len,reverse=True):ref=ref.replace(name,labels[name])
    return ref

def stage_key(key):
    aliases={'mt':'mat','mk':'mrk','lk':'luk','jn':'jhn','1sm':'1sa','ps':'psa','prv':'pro','ez':'ezk','jl':'jol','am':'amo','mi':'mic','hb':'hab','acts':'act','jude':'jud'}
    head,sep,tail=key.partition('_')
    return aliases.get(head,head)+(sep+tail if sep else '')

def quotation(key,fr,to,aref,bref,description):
    """Admisión limitada al contenido recibido, no al volumen entero ni a un códice."""
    fs='stage_'+stage_key(fr);ts='stage_'+stage_key(to);fid='form_quote_'+key
    sa,sb=passage(aref),passage(bref);ea='ev_receive_'+key;eb='ev_identify_'+key;cid='claim_access_'+key
    scope=p('Contenido de '+ref_es(aref)+' identificable en '+ref_es(bref)+'; no demuestra acceso al libro completo.', 'Content from '+aref+' identifiable in '+bref+'; it does not establish access to the whole book.')
    limits=[p('El ejemplar, su procedencia y el medio material de acceso no se conocen.', 'The exemplar, its provenance and the material access medium are unknown.'),p('Puede haber mediación por una colección de citas, liturgia, enseñanza o memoria; no se exige posesión de un volumen completo.', 'A quotation collection, liturgy, teaching or memory may mediate access; possession of a complete volume is not required.'),p('Consulta de textos traducidos y referencias editoriales; no se ha realizado una colación de manuscritos ni un cotejo griego/hebreo propio.', 'Consultation of translated texts and editorial references; no manuscript collation or original Greek/Hebrew comparison was performed.'),p('Una escena de lectura o un discurso narrado no se toma como prueba de que el episodio ocurrió. Se evalúa el acceso del responsable del texto receptor al contenido incorporado.', 'A reading scene or narrated speech is not taken as proof that the episode occurred. Access by the receiving text’s author or editor to the included content is assessed.')]
    D['forms'].append(dict(id=fid,stage_id=fs,language=None,scope=scope,existence_date_ids=[],availability_claim_ids=[cid],notes=p('Forma pertinente anterior a la recepción, inferida de la cita. La edición completa y la lengua exacta del intermediario permanecen abiertas.', 'Pertinent form preceding reception, inferred from the quotation. The complete edition and the exact intermediary language remain open.')))
    D['evidence'].append(dict(id=ea,kind='ancient_testimony',basis_id='basis_receiving_'+key,summary=p(*description),citations=[dict(source_id=sb,locator=p(ref_es(bref),bref))],supports_claim_ids=[cid],limitations=limits[:2]))
    D['evidence'].append(dict(id=eb,kind='published_textual_comparison',basis_id='basis_source_content_'+key,summary=p('El contenido de '+ref_es(aref)+' y las referencias de la edición NABRE permiten identificar el antecedente pertinente. Se documenta la identificación publicada, no un cotejo propio de originales.', 'The content of '+aref+' and NABRE editorial references identify the pertinent antecedent. This records published identification, not an original-language comparison of our own.'),citations=[dict(source_id=sa,locator=p(ref_es(aref),aref)),dict(source_id=sb,locator=p('Pasaje y referencias al antecedente.','Passage and antecedent references.'))],supports_claim_ids=[cid],limitations=[limits[2]]))
    D['claims'].append(dict(id=cid,subject_id=ts,predicate='access_to_quoted_content',value=scope,evidence_ids=[ea,eb],status='supported',certainty_rationale=p('Admisión limitada por convergencia de recepción explícita e identificación textual del contenido.', 'Limited admission through convergence of explicit reception and textual identification of the content.'),counterarguments=limits))
    st=next(s for s in D['stages'] if s['id']==ts);st['claim_ids'].append(cid)
    for sc in D['scenarios']:
        sc['selected_claim_ids'].append(cid)
        attr=next(a for a in sc['selected_attribution_ids'] if next(x for x in D['attributions'] if x['id']==a)['stage_id']==ts)
        checks={k:'supported' for k in ['prior_existence','contextual_availability','linguistic_access','access_before_reception_during_activity']}
        ev=dict(id='access_'+key+('_alt' if sc is alt else ''),from_stage_id=fs,to_stage_id=ts,source_form_id=fid,recipient_attribution_id=attr,scenario_id=sc['id'],status='admitida',checks=checks,check_evidence={k:[ea,eb] for k in checks},evidence_lines=[dict(basis_id='basis_receiving_'+key,evidence_ids=[ea],contribution=p('Recepción explícita del texto como escrito, ley o palabra profética.', 'Explicit reception of the text as writing, law or prophetic speech.')),dict(basis_id='basis_source_content_'+key,evidence_ids=[eb],contribution=p('Identificación del contenido antecedente en otra tradición textual.', 'Identification of antecedent content in another textual tradition.'))],independence_rationale=p('Fundamentos distinguibles: el gesto de citar en B y la identidad del contenido de A. Comparten el pasaje receptor y no son pruebas estadísticamente independientes. No se cuentan dos comentaristas como dos testimonios. La convergencia acredita este contenido, sin probar una ruta de circulación específica.', 'Distinguishable grounds: the act of quotation in B and the identity of A’s content. They share the receiving passage and are not statistically independent. Two commentators are not counted as two witnesses. Convergence establishes access to this content without proving a specific circulation route.'),route=p('Acceso directo o mediado al contenido citado, documentado por su recepción explícita. Canal e institución específicos desconocidos.', 'Direct or mediated access to quoted content, documented by explicit reception. Specific channel and institution are unknown.'),scope=scope,access_time_description=p('Antes de redactar el pasaje receptor, durante la actividad de su responsable. El orden relativo está documentado por la recepción; no depende solo del solapamiento de fechas.', 'Before composing the receiving passage, during its author’s or editor’s activity. Reception documents relative order; it does not rely solely on overlapping date ranges.'),justification=p('Se admite el acceso al fragmento identificado por recepción explícita y correspondencia textual publicada. No se afirma acceso a toda la edición conservada.', 'Access to the identified excerpt is admitted from explicit reception and published textual correspondence. Access to the entire surviving edition is not asserted.'),limitations=limits,dependence=dict(status='supported',evidence_ids=[ea,eb],notes=p('El pasaje muestra uso de contenido antecedente. La dependencia directa de un libro completo o de una edición particular no queda demostrada; la flecha sigue significando acceso.', 'The passage shows use of antecedent content. Direct dependence on a whole book or particular edition is not established; the arrow continues to mean access.')))
        D['access_evaluations'].append(ev)

